#include "dsrrl/runtime/spec_rgb_resource_cache.hpp"
namespace dsrrl::runtime { namespace { spec_rgb_bind_plan fail_open(const operators::resource_bridges::spec_rgb_decision&r,spec_rgb_resource_handle s,spec_rgb_resource_handle t10) noexcept{spec_rgb_bind_plan o;o.route=r;o.preserved_t1_srv=s;o.preserved_t10_srv=t10;return o;} }
spec_rgb_resource_result spec_rgb_resource_cache::register_exact(const std::u16string&n,spec_rgb_resource_handle s,spec_rgb_resource_handle p){if(n.empty())return spec_rgb_resource_result::fail_open_invalid_identity;if(!s||!p)return spec_rgb_resource_result::fail_open_invalid_resource;std::lock_guard<std::mutex>l(mutex_);if(ambiguous_stock_.count(s))return spec_rgb_resource_result::fail_open_conflicting_stock_binding;auto co=name_by_companion_.find(p);if(co!=name_by_companion_.end()&&co->second!=n)return spec_rgb_resource_result::fail_open_conflicting_companion;auto so=name_by_stock_.find(s);if(so!=name_by_stock_.end()&&so->second!=n){auto q=by_name_.find(so->second);if(q!=by_name_.end()){name_by_companion_.erase(q->second.ptde_t10_srv);q->second.stock_t1_srv=0;q->second.ptde_t10_srv=0;q->second.ambiguous=true;}name_by_stock_.erase(so);ambiguous_stock_.insert(s);return spec_rgb_resource_result::fail_open_conflicting_stock_binding;}auto f=by_name_.find(n);if(f==by_name_.end()){by_name_.emplace(n,entry{n,s,p,false});name_by_stock_[s]=n;name_by_companion_[p]=n;return spec_rgb_resource_result::registered;}auto&e=f->second;if(e.ambiguous)return spec_rgb_resource_result::fail_open_ambiguous_identity;if(e.stock_t1_srv==s&&e.ptde_t10_srv==p)return spec_rgb_resource_result::already_registered;name_by_stock_.erase(e.stock_t1_srv);name_by_companion_.erase(e.ptde_t10_srv);e.stock_t1_srv=0;e.ptde_t10_srv=0;e.ambiguous=true;return spec_rgb_resource_result::fail_open_conflicting_companion;}
spec_rgb_bind_plan spec_rgb_resource_cache::plan_bind(const spec_rgb_bind_request&r)const{auto d=operators::resource_bridges::evaluate_spec_rgb_route(r.route);auto o=fail_open(d,r.currently_bound_t1,r.currently_bound_t10);if(d.action!=operators::resource_bridges::spec_rgb_action::bind_ptde_t10_rgb||r.logical_name.empty()||!r.currently_bound_t1)return o;std::lock_guard<std::mutex>l(mutex_);if(ambiguous_stock_.count(r.currently_bound_t1))return o;auto f=by_name_.find(r.logical_name);if(f==by_name_.end()||f->second.ambiguous)return o;auto&e=f->second;if(!e.stock_t1_srv||!e.ptde_t10_srv||e.stock_t1_srv!=r.currently_bound_t1)return o;auto c=name_by_companion_.find(e.ptde_t10_srv);if(c==name_by_companion_.end()||c->second!=r.logical_name)return o;o.activate=true;o.ptde_t10_srv=e.ptde_t10_srv;return o;}
void spec_rgb_resource_cache::erase_stock(spec_rgb_resource_handle s){if(!s)return;std::lock_guard<std::mutex>l(mutex_);ambiguous_stock_.erase(s);auto o=name_by_stock_.find(s);if(o==name_by_stock_.end())return;auto f=by_name_.find(o->second);if(f!=by_name_.end()&&f->second.stock_t1_srv==s){name_by_companion_.erase(f->second.ptde_t10_srv);by_name_.erase(f);}name_by_stock_.erase(o);}void spec_rgb_resource_cache::erase_companion(spec_rgb_resource_handle p){if(!p)return;std::lock_guard<std::mutex>l(mutex_);auto o=name_by_companion_.find(p);if(o==name_by_companion_.end())return;auto f=by_name_.find(o->second);if(f!=by_name_.end()&&f->second.ptde_t10_srv==p){name_by_stock_.erase(f->second.stock_t1_srv);by_name_.erase(f);}name_by_companion_.erase(o);}void spec_rgb_resource_cache::clear()noexcept{std::lock_guard<std::mutex>l(mutex_);by_name_.clear();name_by_stock_.clear();name_by_companion_.clear();ambiguous_stock_.clear();}std::size_t spec_rgb_resource_cache::size()const noexcept{std::lock_guard<std::mutex>l(mutex_);return by_name_.size();}}
